    pub fn maybe_eta(mut self, value: Option<crate::typed::support::Float64>) -> Self {
        self.eta = value;
        self
    }

    /// Advanced configuration option.
    /// Specifies the rate at which `eta` increases for each new tree that is added to the forest.
    /// For example, a rate of 1.05 increases `eta` by 5% for each extra tree.
    /// By default, this value is calculated during hyperparameter optimization.
    /// It must be between `0.5` and `2`.
    pub fn eta_growth_rate_per_tree(
        mut self,
        value: impl Into<crate::typed::support::Float64>,
    ) -> Self {
        self.eta_growth_rate_per_tree = Some(value.into());
        self
    }

    /// Sets [`eta_growth_rate_per_tree`](Self::eta_growth_rate_per_tree) if `value` is `Some`.
