#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct TrainedModelConfig {
    /// Identifier for the trained model.
    pub model_id: crate::typed::_types::Id,
    /// The model type
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub model_type: Option<TrainedModelType>,
    /// A comma delimited string of tags. A trained model can have many tags, or none.
    pub tags: Vec<String>,
    /// The Elasticsearch version number in which the trained model was created.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub version: Option<crate::typed::_types::VersionString>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub compressed_definition: Option<String>,
    /// Information on the creator of the trained model.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub created_by: Option<String>,
    /// The time when the trained model was created.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub create_time: Option<crate::typed::_types::DateTime>,
    /// Any field map described in the inference configuration takes precedence.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub default_field_map: Option<indexmap::IndexMap<String, String>>,
    /// The free-text description of the trained model.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    /// The estimated heap usage in bytes to keep the trained model in memory.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub estimated_heap_memory_usage_bytes: Option<i32>,
    /// The estimated number of operations to use the trained model.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub estimated_operations: Option<i32>,
    /// True if the full model definition is present.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fully_defined: Option<bool>,
    /// The default configuration for inference. This can be either a regression, classification, or one of the many NLP focused configurations. It must match the underlying definition.trained_model's target_type. For pre-packaged models such as ELSER the config is not required.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub inference_config: Option<InferenceConfigCreateContainer>,
    /// The input field names for the model definition.
    pub input: TrainedModelConfigInput,
    /// The license level of the trained model.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub license_level: Option<String>,
    /// An object containing metadata about the trained model. For example, models created by data frame analytics contain analysis_config and input objects.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub metadata: Option<TrainedModelConfigMetadata>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub model_size_bytes: Option<crate::typed::_types::ByteSize>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub model_package: Option<ModelPackageConfig>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub location: Option<TrainedModelLocation>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub platform_architecture: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub prefix_strings: Option<TrainedModelPrefixStrings>,
}

